-- Tab icons: a sprite sheet (9 icons, 48x48 px each, white on transparent, embedded) written to the workspace once.
-- Icons.Make(parent, index, size, pos) -> ImageLabel (tint it with ImageColor3), or nil when the executor cannot load images.
-- 1 car, 2 person, 3 eye, 4 crosshair, 5 pin, 6 coin, 7 hud, 8 folder, 9 gear
local Icons = { Cell = 48, Count = 9 }
local DATA = ""
local path = "ScrdsxScript/icons_v1.png"
local cached

local function decode(s)
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, #chars do map[chars:sub(i, i)] = i - 1 end
	local out, buf, bits = {}, 0, 0
	for i = 1, #s do
		local v = map[s:sub(i, i)]
		if v then
			buf = buf * 64 + v
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				local byte = math.floor(buf / 2 ^ bits)
				out[#out + 1] = string.char(byte)
				buf = buf - byte * 2 ^ bits
			end
		end
	end
	return table.concat(out)
end

function Icons.Get()
	if cached ~= nil then return cached or nil end
	cached = false
	pcall(function()
		if not (writefile and getcustomasset) then return end
		pcall(function() if makefolder then makefolder("ScrdsxScript") end end)
		if not (isfile and isfile(path)) then writefile(path, decode(DATA)) end
		cached = getcustomasset(path)
	end)
	return cached or nil
end

function Icons.Make(parent, index, size, pos)
	local id = Icons.Get()
	if not id or not index then return nil end
	local el = Instance.new("ImageLabel")
	el.BackgroundTransparency = 1
	el.Image = id
	el.ImageRectSize = Vector2.new(Icons.Cell, Icons.Cell)
	el.ImageRectOffset = Vector2.new((index - 1) * Icons.Cell, 0)
	el.Size = UDim2.fromOffset(size, size)
	if pos then el.Position = pos end
	el.Parent = parent
	return el
end

return Icons
